class Node:
    def __init__(self, val, nxt=None):
        self.val, self.nxt = val, nxt

def build(xs):
    head = None
    for x in reversed(xs):
        head = Node(x, head)
    return head

def drop(head, k):
    dummy = Node(0, head)
    prev, cnt = dummy, 1
    while prev.nxt:
        if cnt % k == 0:
            prev.nxt = prev.nxt.nxt
        else:
            prev = prev.nxt
        cnt += 1
    return dummy.nxt

def swap_pairs(head):
    dummy = Node(0, head)
    p = dummy
    while p.nxt and p.nxt.nxt:
        a, b = p.nxt, p.nxt.nxt
        a.nxt, b.nxt, p.nxt = b.nxt, a, b
        p = a
    return dummy.nxt

h = swap_pairs(drop(build([1, 2, 3, 4, 5, 6, 7, 8, 9]), 3))
out = []
while h:
    out.append(h.val)
    h = h.nxt
print(out)
```

